import { api, PAGE_SIZE, urlUtils } from '@igblsln/store';
export const customApi = api.injectEndpoints({
    overrideExisting: false,
    endpoints: (build) => ({
        listAllReportsToExport: build.query({
            query: ({ year, month, includes }) => {
                return {
                    url: urlUtils('/reports/export_report/', `?year=${year}&month=${month}&include=${includes === null || includes === void 0 ? void 0 : includes.join(',')}`),
                };
            },
        }),
        // Same API endpoints used on vendor payment page
        listVendorPaymentInvoice: build.query({
            query: ({ page, size, year, month }) => {
                let url = urlUtils('/vendor/payment/', `all?page=${page}&page_size=${size || PAGE_SIZE}&pay_invoice=1`);
                if (year)
                    url += `&year=${year}`;
                if (month)
                    url += `&month=${month}`;
                return { url };
            },
            providesTags: (result) => result
                ? [
                    ...result.results.map(({ key }) => ({ type: 'VENDOR_PAYMENT_INVOICE', id: key })),
                    { type: 'VENDOR_PAYMENT_INVOICE', id: 'LIST' },
                ]
                : [{ type: 'VENDOR_PAYMENT_INVOICE', id: 'LIST' }],
        }),
        // Same API endpoints used on contractor payment page
        listContractorPaymentInvoice: build.query({
            query: ({ page, size }) => {
                return {
                    url: urlUtils('/contract/payment/', `all?page=${page}&page_size=${size || PAGE_SIZE}&pay_invoice=1`),
                };
            },
            providesTags: (result) => result
                ? [
                    ...result.results.map(({ key }) => ({ type: 'CONTRACTOR_PAYMENT_INVOICE', id: key })),
                    { type: 'CONTRACTOR_PAYMENT_INVOICE', id: 'LIST' },
                ]
                : [{ type: 'CONTRACTOR_PAYMENT_INVOICE', id: 'LIST' }],
        }),
        getErrorProne: build.query({
            query: () => 'error-prone',
        }),
    }),
});
export const { useListAllReportsToExportQuery, useLazyListAllReportsToExportQuery, useLazyListVendorPaymentInvoiceQuery, useLazyListContractorPaymentInvoiceQuery, useGetErrorProneQuery } = customApi;
