import { api, PAGE_SIZE, urlUtils } from '@igblsln/store';
export const customApi = api.injectEndpoints({
    overrideExisting: false,
    endpoints: (build) => ({
        listContractorTDSReports: build.query({
            query: ({ page, size, year, month }) => {
                return {
                    url: urlUtils('/reports/contractor_tds_report/', `?page=${page || 1}&page_size=${size || PAGE_SIZE}&year=${year}&month=${month}`),
                };
            },
        }),
        getErrorProne: build.query({
            query: () => 'error-prone',
        }),
    }),
});
export const { useListContractorTDSReportsQuery, useGetErrorProneQuery } = customApi;
